def destinataires_existants(apps, schema_editor):
    """Résultats déjà reçus : on leur trouve leur médecin comme le fera
    l'intégration (prescripteur, à défaut médecin de la consultation). Ils
    restent « non ouverts » : le médecin ne les a jamais vus signalés."""
    Analyse = apps.get_model('laboratoire', 'AnalyseLaboratoire')

    def compte(medecin):
        if medecin is None:
            return None
        if medecin.user_id:
            return medecin.user_id
        employe = getattr(medecin, 'employe', None)
        return getattr(employe, 'user_id', None)

    for analyse in Analyse.objects.filter(destinataire__isnull=True, demande__isnull=False):
        demande = analyse.demande
        user_id = compte(demande.medecin_prescripteur)
        if user_id is None and demande.rendez_vous_id:
            user_id = compte(demande.rendez_vous.medecin)
        if user_id:
            analyse.destinataire_id = user_id
            analyse.save(update_fields=['destinataire'])


